// Every emoji the bundled Twemoji font has, with shortcodes, for the picker and `:name` autocomplete.
// emoji-list.json is generated by scripts/build-emoji-data.mjs from emojibase-data.
import LIST from './emoji-list.json';
import { msg } from './msg';

// Picker sections in the generated list, with the emoji its category bar shows.
const GROUPS: Record<string, { label: string; icon: string }> = {
  Smileys: { label: msg('Smileys'), icon: '😀' },
  People: { label: msg('People'), icon: '👋' },
  Nature: { label: msg('Nature'), icon: '🐻' },
  Food: { label: msg('Food'), icon: '🍔' },
  Activities: { label: msg('Activities'), icon: '⚽' },
  Travel: { label: msg('Travel'), icon: '🚗' },
  Objects: { label: msg('Objects'), icon: '💡' },
  Symbols: { label: msg('Symbols'), icon: '🔣' },
  Flags: { label: msg('Flags'), icon: '🏁' },
};

/** Skin tone modifiers, light to dark; tone 0 is the default yellow. */
export const SKIN_TONES = ['🏻', '🏼', '🏽', '🏾', '🏿'];

export interface EmojiEntry {
  char: string;
  names: string[];
  tags: string[];
  /** 1 = the tone goes after the first character; otherwise the five variants. */
  skins?: 1 | string[];
}

type Raw = [string, string, string, (1 | string[])?];

export const EMOJI_GROUPS: { id: string; name: string; icon: string; emojis: EmojiEntry[] }[] = (
  LIST as unknown as [string, Raw[]][]
).map(([id, list]) => ({
  id,
  name: GROUPS[id].label,
  icon: GROUPS[id].icon,
  emojis: list.map(([char, names, tags, skins]) => ({
    char,
    names: names.split(' '),
    tags: tags ? tags.split(' ') : [],
    skins,
  })),
}));

export const ALL_EMOJI = EMOJI_GROUPS.flatMap((g) => g.emojis);

/** The emoji in the chosen skin tone (1-5), if it has tones. */
export function withTone(e: EmojiEntry, tone: number): string {
  if (!tone || !e.skins) return e.char;
  if (e.skins !== 1) return e.skins[tone - 1];
  const [first, ...rest] = [...e.char];
  if (rest[0] === '️') rest.shift();
  return first + SKIN_TONES[tone - 1] + rest.join('');
}

/** Shortcodes that start with the query, then ones containing it, then keyword matches ("like" -> 👍). */
export function searchEmoji(q: string, limit = 40): EmojiEntry[] {
  const query = q.toLowerCase().replace(/\s+/g, '_');
  const word = query.replace(/_/g, ' ');
  const tiers: EmojiEntry[][] = [[], [], []];
  for (const e of ALL_EMOJI) {
    if (e.names.some((n) => n.startsWith(query))) tiers[0].push(e);
    else if (e.names.some((n) => n.includes(query))) tiers[1].push(e);
    else if (e.tags.some((t) => t.startsWith(word))) tiers[2].push(e);
  }
  return tiers.flat().slice(0, limit);
}
